def compute_model_placement(gpu_num, models):
    """
    Greedy placement with multiple model orderings, refined by a local
    search that moves single models between GPUs whenever it lowers the
    maximum KVPR. Keeps the best feasible placement found.
    """

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for m in order:
            best, best_kvpr = None, float('inf')
            for g in range(gpu_num):
                rem = free[g] - m.model_size
                if rem <= 0:
                    continue
                kvpr = (load[g] + m.req_rate / m.slo) / rem
                if kvpr < best_kvpr:
                    best_kvpr, best = kvpr, g
            if best is None:
                return None
            placement[best].append(m)
            load[best] += m.req_rate / m.slo
            free[best] -= m.model_size
        return placement

    def score(placement):
        worst = 0.0
        for ms in placement.values():
            if not ms:
                continue
            load = sum(m.req_rate / m.slo for m in ms)
            free = GPU_MEM_SIZE - sum(m.model_size for m in ms)
            if free <= 0:
                return float('inf')
            worst = max(worst, load / free)
        return worst

    def local_search(placement):
        """Steepest descent: each iteration, evaluate all single-model moves
        and all pairwise swaps, apply the one change that most reduces the
        max KVPR, and stop when no change helps."""
        while True:
            best_score = score(placement)
            best_action = None
            for src in range(gpu_num):
                for m in list(placement[src]):
                    for dst in range(gpu_num):
                        if dst == src:
                            continue
                        if GPU_MEM_SIZE - sum(x.model_size for x in placement[dst]) - m.model_size <= 0:
                            continue
                        placement[src].remove(m)
                        placement[dst].append(m)
                        s = score(placement)
                        if s < best_score:
                            best_score, best_action = s, ('move', m, src, dst)
                        placement[dst].remove(m)
                        placement[src].append(m)
            for a in range(gpu_num):
                for b in range(a + 1, gpu_num):
                    for ma in list(placement[a]):
                        for mb in list(placement[b]):
                            placement[a].remove(ma); placement[b].remove(mb)
                            placement[a].append(mb); placement[b].append(ma)
                            s = score(placement)
                            if s < best_score:
                                best_score, best_action = s, ('swap', ma, mb, a, b)
                            placement[a].remove(mb); placement[b].remove(ma)
                            placement[a].append(ma); placement[b].append(mb)
            if best_action is None:
                break
            if best_action[0] == 'move':
                _, m, src, dst = best_action
                placement[src].remove(m)
                placement[dst].append(m)
            else:
                _, ma, mb, a, b = best_action
                placement[a].remove(ma); placement[b].remove(mb)
                placement[a].append(mb); placement[b].append(ma)
        return placement

    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / max(m.model_size, 1e-9), reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / max(m.model_size, 1e-9)),
        list(models),
    ]

    best_result, best_score = None, float('inf')
    for order in orders:
        result = greedy(order)
        if result is None:
            continue
        result = local_search(result)
        s = score(result)
        if s < best_score:
            best_score, best_result = s, result

    if best_result is None:
        raise ValueError("Unable to place all models within GPU memory.")
    return best_result

